COLORS = ('#79bff2', '#65d5af', '#72d8cd', '#a2d17c', '#edc875', '#eda879', '#d592e2', '#9c9feb')
STYLE = '''
QDialog { background:#10151e; }
QWidget { color:#dce5f1; font-family:Arial; font-size:12px; }
QLabel#Title { font-size:25px; font-weight:bold; color:#f5f8ff; }
QLabel#Muted { color:#8e9fb6; }
QGroupBox { background:#18212e; border:1px solid #28364a; border-radius:9px; margin-top:18px; padding:12px; }
QGroupBox::title { subcontrol-origin:margin; left:12px; color:#72d8cd; }
QPushButton { background:#233146; border:1px solid #34465f; border-radius:7px; padding:8px 13px; }
QPushButton:hover { background:#30435e; border-color:#74cfc9; }
QPushButton:checked { background:#214a50; color:#92f1e3; border-color:#58bcaf; }
QPushButton#Primary { background:#73dccc; color:#10252a; font-weight:bold; }
QPushButton:disabled { color:#58687d; background:#192332; }
QComboBox,QDoubleSpinBox { background:#101925; border:1px solid #35465c; border-radius:6px; padding:5px; }
QComboBox QAbstractItemView { background:#1c293b; color:#eef4ff; selection-background-color:#32565e; }
QCheckBox { spacing:7px; }
QCheckBox::indicator { width:16px; height:16px; border:1px solid #53667e; border-radius:4px; background:#111c29; }
QCheckBox::indicator:checked { background:#65cbbb; border:3px solid #b1f8e6; }
QSplitter::handle { background:#28364a; height:6px; width:6px; }
QToolTip { background:#233146; color:#eef4ff; border:1px solid #74cfc9; }
'''
